export const getPostPaymentsRetryUrl = (id: string,) => {




  return `/v1/payments/${id}/retry`
}

/**
 * Creates a new payment with a new `ourRef`, linked via `retryOfId`.
 * @summary Retry a failed payment
 */
export const postPaymentsRetry = async (id: string,
    retryPaymentDto: RetryPaymentDto, options?: Parameters<typeof apiFetch>[1]): Promise<PaymentViewResponseDto> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<PaymentViewResponseDto>(getPostPaymentsRetryUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(retryPaymentDto)
  }
);}





export const getPostPaymentsRetryMutationKey = () => ['postPaymentsRetry'] as const;

export const getPostPaymentsRetryMutationOptions = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof postPaymentsRetry>>, TError,PostPaymentsRetryMutationVariables, TContext>, request?: SecondParameter<typeof apiFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof postPaymentsRetry>>, TError,PostPaymentsRetryMutationVariables, TContext> => {

const mutationKey = getPostPaymentsRetryMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof postPaymentsRetry>>, PostPaymentsRetryMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  postPaymentsRetry(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type PostPaymentsRetryMutationResult = NonNullable<Awaited<ReturnType<typeof postPaymentsRetry>>>
    export type PostPaymentsRetryMutationBody = BodyType<RetryPaymentDto>
    export type PostPaymentsRetryMutationError = ErrorType<void>
    export type PostPaymentsRetryMutationVariables = {id: string;data: BodyType<RetryPaymentDto>}

